## make_tables.R - R port of wp4_islets/make_tables.py: WP4: collect the numbers of every result file into one Markdown file (WP4_summary_tables.md) so that the README and the manuscript revision quote files, not memory.
## Reads results/index.csv, results/*__cons.csv, results/*__detection.csv, meta/*, metacell/metacell_summary.csv, perturbation/*. Writes WP4_summary_tables.md. No analysis.
## Folders: WP4_TAB_RES, WP4_TAB_META, WP4_TAB_MC, WP4_TAB_PERT (default results_R/wp4/results, meta, metacell, perturbation; the candidate decisions come from the archived perturbation folder: WP4_TAB_CAND); output WP4_TAB_OUT
## (default results_R/wp4/WP4_summary_tables.md).   Usage: Rscript make_tables.R
HERE <- dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE)[1]))); R_PORT <- normalizePath(file.path(HERE, ".."))
source(file.path(R_PORT, "pycompat.R")); suppressMessages(library(jsonlite)); options(py_json_nan = TRUE)
W4 <- file.path(R_PORT, "results_R", "wp4"); RES <- Sys.getenv("WP4_TAB_RES", file.path(W4, "results")); META <- Sys.getenv("WP4_TAB_META", file.path(W4, "meta")); MC <- Sys.getenv("WP4_TAB_MC", file.path(W4, "metacell"))
PERT <- Sys.getenv("WP4_TAB_PERT", file.path(W4, "perturbation")); CAND <- Sys.getenv("WP4_TAB_CAND", normalizePath(file.path(R_PORT, "..", "wp4_islets", "perturbation"))); OUTF <- Sys.getenv("WP4_TAB_OUT", file.path(W4, "WP4_summary_tables.md"))
TAGS <- c("gse81608", "gse84133_human", "gse86469", "gse81547", "emtab5061", "gse84133_mouse")
NAME <- c(gse81608 = "GSE81608", gse84133_human = "GSE84133 human", gse86469 = "GSE86469", gse81547 = "GSE81547", emtab5061 = "E-MTAB-5061", gse84133_mouse = "GSE84133 mouse")
GENES <- c("Hes1", "Wnt5a", "Wnt5b", "Wnt9a", "Lef1", "Tcf7", "Tcf7l2", "Itpr1", "Ryr2", "Ryr3", "Cacna1c", "Cacna1d", "Kcnj11", "Ptbp1", "Glut2", "Ins1", "Glp1r")
f <- function(x, d = 3, sign = FALSE) { if (is.null(x) || is.na(x)) return("-"); if (sign) paste0(if (x < 0 || (x == 0 && 1 / x < 0)) "-" else "+", py_fmt_f(abs(x), d)) else py_fmt_f(x, d) }
md <- function(rows, header) c(paste0("| ", paste(header, collapse = " | "), " |"), paste0("|", paste(rep("---", length(header)), collapse = "|"), "|"), vapply(rows, function(r) paste0("| ", paste(r, collapse = " | "), " |"), ""))
rd <- function(p) read.csv(p, stringsAsFactors = FALSE, check.names = FALSE, na.strings = "")
I <- rd(file.path(RES, "index.csv")); out <- c("# WP4 summary tables (generated by make_tables.py from the result files; no analysis)", "")
pick <- function(t, v, m) I[I$tag == t & I$variant == v & I$mode == m, ][1, ]
## ---- Table 1
rows <- list()
for (t in TAGS) { u <- pick(t, "primary", "unadjusted"); a <- pick(t, "primary", "adjusted")
  rows[[length(rows) + 1]] <- c(NAME[[t]], as.integer(a$beta_cells), as.integer(a$donors), as.integer(a$t2d_beta_cells), a$kind, a$depth_covariate, as.integer(a$genes_evaluable), as.integer(a$consensus_pairs_evaluable), f(u$median_rho_consensus, 3, TRUE), f(u$null_median_rho_mean),
                                f(a$median_rho_consensus, 3, TRUE), f(a$null_median_rho_mean), f(a$E, 3, TRUE), f(a$SE_E), f(a$empirical_p_E), sprintf("%d / %d", as.integer(a$consensus_sig_positive_q05), as.integer(a$consensus_sig_negative_q05))) }
out <- c(out, "## Table 1. Cell-level analysis of each dataset (all frozen beta-cells; primary variant)", "", md(rows, c("dataset", "beta-cells", "donors", "beta-cells from T2D donors", "data", "depth covariate", "evaluable genes (of 17)", "evaluable consensus pairs (of 21)", "median rho, not adjusted", "matched-null median, not adjusted",
                                                                                                                    "median rho, depth-adjusted", "matched-null median, depth-adjusted", "E (depth-adjusted)", "SE of E", "empirical P of E", "pairs q<0.05 positive / negative (depth-adjusted)")), "")
rows <- list()
for (t in TAGS) { s <- I[I$tag == t & I$variant == "nondiabetic", ]; if (nrow(s) == 0) next
  for (m in c("unadjusted", "adjusted")) { r <- s[s$mode == m, ][1, ]; rows[[length(rows) + 1]] <- c(NAME[[t]], m, as.integer(r$beta_cells), as.integer(r$donors), as.integer(r$genes_evaluable), as.integer(r$consensus_pairs_evaluable), f(r$median_rho_consensus, 3, TRUE), f(r$null_median_rho_mean), f(r$E, 3, TRUE), f(r$SE_E)) } }
out <- c(out, "## Table 1b. Sensitivity: non-diabetic donors only (datasets with donors who have type 2 diabetes)", "", md(rows, c("dataset", "mode", "beta-cells", "donors", "evaluable genes", "evaluable consensus pairs", "median rho", "matched-null median", "E", "SE of E")), "")
## ---- Table 2: evaluable genes and pairs
det <- list(); for (t in TAGS) { d <- rd(file.path(RES, sprintf("%s__primary__adjusted__detection.csv", t))); det[[t]] <- setNames(as.logical(d$evaluable), d$gene_invitro) }
rows <- list(); for (t in TAGS) { d <- det[[t]]; ev <- GENES[d[GENES]]; ne <- GENES[!d[GENES]]; rows[[length(rows) + 1]] <- c(NAME[[t]], length(ev), paste(ev, collapse = ", "), paste(ne, collapse = ", ")) }
out <- c(out, "## Table 2. Evaluable genes (detected in at least 10% of the beta-cells)", "", md(rows, c("dataset", "n", "evaluable", "not evaluable")), "")
pp <- rd(file.path(RES, "gse81608__primary__adjusted__pairs.csv")); pp <- pp[as.logical(pp$consensus_invitro), c("gene1", "gene2")]; cons <- lapply(seq_len(nrow(pp)), function(i) c(pp$gene1[i], pp$gene2[i]))
cc <- list(); for (t in TAGS) { d <- rd(file.path(RES, sprintf("%s__primary__adjusted__cons.csv", t))); cc[[t]] <- setNames(d$rho, paste(d$gene1, d$gene2)) }
rows <- list()
for (p in cons) { k <- paste(p[1], p[2]); cells <- vapply(TAGS[1:5], function(t) if (k %in% names(cc[[t]])) f(cc[[t]][[k]], 2, TRUE) else "NE", ""); nh <- sum(vapply(TAGS[1:5], function(t) k %in% names(cc[[t]]), TRUE))
  rows[[length(rows) + 1]] <- c(paste0(p[1], "-", p[2]), unname(cells), if (k %in% names(cc$gse84133_mouse)) f(cc$gse84133_mouse[[k]], 2, TRUE) else "NE", nh) }
out <- c(out, "## Table 2b. The 21 consensus pairs: depth-adjusted partial Spearman rho per dataset (NE = not evaluable); last column = number of human datasets in which the pair is evaluable", "", md(rows, c("pair", unname(NAME[TAGS]), "human datasets evaluable")), "")
n0 <- vapply(cons[vapply(rows, function(r) r[length(r)] == "0", TRUE)], function(p) paste0(p[1], "-", p[2]), ""); out <- c(out, sprintf("Pairs not evaluable in any human dataset (%d): %s.", length(n0), paste(n0, collapse = ", ")), "")
## ---- Table 3: meta-analysis
ms <- fromJSON(file.path(META, "meta_summary.json"), simplifyVector = FALSE); rows <- list()
for (v in ms$variants) for (e in v$estimators) rows[[length(rows) + 1]] <- c(v$variant, v$mode, paste(unlist(v$qualifying), collapse = ", "), e$estimator, f(e$mu, 3, TRUE), sprintf("[%s, %s]", f(e$lo, 3, TRUE), f(e$hi, 3, TRUE)), f(e$tau2, 4), sprintf("%.0f%%", 100 * e$I2), e$verdict)
out <- c(out, "## Table 3. Random-effects meta-analysis of E (margin +/-0.10; primary = depth-adjusted, all donors, REML + Hartung-Knapp)", "", md(rows, c("variant", "mode", "datasets", "estimator", "pooled E", "95% CI", "tau2", "I2", "verdict by the fixed rule")), "")
rows <- list(); for (v in ms$variants) for (e in v$leave_one_out) rows[[length(rows) + 1]] <- c(v$variant, v$mode, e$left_out, f(e$mu, 3, TRUE), sprintf("[%s, %s]", f(e$lo, 3, TRUE), f(e$hi, 3, TRUE)), e$verdict)
out <- c(out, "## Table 3b. Leave-one-dataset-out (REML + Hartung-Knapp)", "", md(rows, c("variant", "mode", "left out", "pooled E", "95% CI", "verdict")), "")
P <- rd(file.path(META, "pair_level_pooled_rho.csv")); P <- P[order(-P$pooled_rho, method = "radix"), ]
out <- c(out, "## Table 4. Pair-level pooled rho (consensus pairs evaluable in at least 3 human datasets; depth-adjusted; REML + Hartung-Knapp on Fisher z)", "",
         md(lapply(seq_len(nrow(P)), function(i) { r <- P[i, ]; c(paste0(r$gene1, "-", r$gene2), r$datasets, gsub(";", " / ", r$rho_by_dataset, fixed = TRUE), f(r$pooled_rho, 3, TRUE), sprintf("[%s, %s]", f(r$lo, 3, TRUE), f(r$hi, 3, TRUE)), sprintf("%.0f%%", 100 * r$I2)) }), c("pair", "datasets", "rho by dataset (order of the dataset table)", "pooled rho", "95% CI", "I2")), "")
## ---- Table 5: metacell
p <- file.path(MC, "metacell_summary.csv")
if (file.exists(p)) {
  M <- rd(p); rows <- list(); rg <- function(m, lo, hi, d, sign = FALSE, sep = "-") if (is.na(m)) "-" else sprintf("%s (%s%s%s)", f(m, d, sign), f(lo, d, sign), if (sign) " to " else sep, f(hi, d, sign))
  for (i in seq_len(nrow(M))) { r <- M[i, ]
    rows[[length(rows) + 1]] <- c(if (r$tag %in% names(NAME)) NAME[[r$tag]] else r$tag, as.integer(r$size), sprintf("%d / %d", as.integer(r$partitions_with_pairs), as.integer(r$partitions)), f(r$donors_used_median, 0), f(r$metacells_median, 0), rg(r$genes_evaluable_med, r$genes_evaluable_min, r$genes_evaluable_max, 0),
                                  rg(r$consensus_pairs_evaluable_med, r$consensus_pairs_evaluable_min, r$consensus_pairs_evaluable_max, 0), if (!is.na(r$cell_level_pairs)) as.integer(r$cell_level_pairs) else "-", f(r$cell_level_median_rho, 3, TRUE),
                                  rg(r$median_rho_med, r$median_rho_min, r$median_rho_max, 3, TRUE), rg(r$E_med, r$E_min, r$E_max, 3, TRUE), f(r$SE_E_med)) }
  out <- c(out, "## Table 5. Metacell sensitivity (20 random partitions per size; median and range over the partitions; evaluable = nonzero in at least 50% of metacells)", "",
           md(rows, c("dataset", "metacell size", "partitions with an evaluable pair", "donors used", "metacells", "evaluable genes", "evaluable consensus pairs", "cell level: pairs (10% rule)", "cell level: median rho", "metacell median rho", "metacell E", "median SE of E")), "")
}
## ---- Table 6: perturbation
Cd <- rd(file.path(CAND, "candidates_decisions.csv")); g <- fromJSON(file.path(PERT, "gse60803_concordance.json"), simplifyVector = FALSE); vc <- sort(table(Cd$decision), decreasing = TRUE)
out <- c(out, "## Table 6. Perturbation concordance (protocol 4.6)", "", sprintf("Candidates from the two fixed queries: %d unique series (%s); kept %d, dropped %d.", nrow(Cd), paste(sprintf("%s %d", names(vc), as.integer(vc)), collapse = ", "), sum(Cd$decision == "keep"), sum(Cd$decision == "drop")), "")
rows <- list(); for (k in list(c("all_donors", "primary: 4 donors, perturbed mean minus control"), c("S114_only", "secondary: donor S114 only (nontarget control, n = 1)"))) { d <- g[[k[1]]]; rows[[length(rows) + 1]] <- c(k[2], d$n_genes, d$n_same_sign, f(d$binomial_p), f(d$spearman_rho, 3, TRUE), f(d$spearman_p)) }
out <- c(out, md(rows, c("GSE60803 contrast against the INS-1 DKK-1 arm", "genes", "same sign", "exact binomial P", "Spearman rho", "P of rho")), "", paste0("Same sign (primary): ", paste(unlist(g$all_donors$same_sign_genes), collapse = ", "), ". Opposite sign: ", paste(unlist(g$all_donors$opposite_sign_genes), collapse = ", "), "."), "")
dir.create(dirname(OUTF), showWarnings = FALSE, recursive = TRUE); write_text_bytes(gsub("\n", .NL, paste(out, collapse = "\n"), fixed = TRUE), OUTF); cat("written WP4_summary_tables.md,", length(out), "blocks\n")
